  // STEP 1: Check guardrails first - redirect if off-topic
  const guardrailMessage = checkGuardrails(request.message)
  if (guardrailMessage) {
    console.log('[AI Chat v5] Off-topic query detected, redirecting')
    return {
      message: guardrailMessage,
      recommendedProducts: [],
      looks: [],
      sessionContext,
