267→export function getClarificationsNeeded(
268→  query: UserQuery,
269→  conversationHistory?: Array<{ role: string; content: string }>,
270→  askedClarifications?: Array<'gender' | 'occasion' | 'destination' | 'budget'>,
271→  storedContext?: { gender?: 'men' | 'women'; occasion?: string; destination?: string; budget?: number },
272→  clarificationTurnCount?: number,
273→  hasProvidedRecommendations?: boolean
274→): ClarificationNeeded[] {
275→  const clarifications: ClarificationNeeded[] = [];
276→  const asked = askedClarifications || [];
277→  const turnCount = clarificationTurnCount !== undefined ? clarificationTurnCount : asked.length;
278→
279→  // CRITICAL v2.2: POST-RECOMMENDATION LOCKOUT (Step 4)
280→  // If recommendations have been provided, NEVER ask clarifications again
281→  if (hasProvidedRecommendations) {
282→    console.log('[Clarification Detector] 🔒 POST-RECOMMENDATION LOCKOUT ACTIVE (Step 4)');
283→    console.log('[Clarification Detector] Returning EMPTY array - system is in FOLLOW-UP mode.');
284→    return [];
285→  }
286→
287→  // CRITICAL: LOOP PREVENTION - MAX 2 CLARIFICATIONS (v2.1)
288→  // If already asked 2 clarifications, return empty array (force recommendations)
289→  if (turnCount >= 2) {
290→    console.log('[Clarification Detector] 🔴 MAX 2 clarifications reached. Force recommendations mode.');
291→    console.log('[Clarification Detector] Returning EMPTY array - system will provide recommendations.');
292→    return [];
293→  }
294→
